;=============================================================================
; Battletoads (E) - sound engine, PRG bank 3 ($8000-$FFFF, AxROM 32K bank 3)
; Rare, 1991. Labeled disassembly generated by tool/gen_disasm.py.
;
; Covers $851F-$CCCF: PCM generators, music/SFX driver, period table,
; sound effects and all song data. Assemble with:
;   ca65 bt_sound.asm -o bt_sound.o && ld65 -C bt_sound.cfg bt_sound.o -o bt_sound
; and compare bt_sound.0.bin with ROM file offset $0C52F (bank 3 + $051F).
;
; Far-call interface (bank-0 stub $FFCB: X = jump-table offset, Y = bank 3):
;   X=$03 Music_Init  ($32 = song)      X=$06 Music_Update (every frame)
;   X=$09 Pcm_PlayFullVol               X=$18/$1B Pcm_Play (pending drum)
;   X=$0C/$0F/$12/$15 Sfx_PlaySq1/Sq2/Tri/Noise ($39 = sound effect id)
;=============================================================================

.setcpu "6502"

;-----------------------------------------------------------------------------
; RAM
;-----------------------------------------------------------------------------
FarCallLo              = $13    ; bank-call vector (game)
Rng0                   = $25    ; random generator state
Rng1                   = $26
Rng2                   = $27
Rng3                   = $28    ; incremented after every PCM sample
TempoAcc               = $32    ; tempo accumulator (also: song number passed to Music_Init)
Tempo                  = $33    ; added to TempoAcc every frame; carry = tick
TickFlag               = $34    ; bit 7 set on tick frames
DataPtr                = $37    ; track/SFX data pointer (2 bytes)
DataPtrHi              = $38
Temp                   = $39    ; scratch; SFX number passed to Sfx_Play*
Temp2                  = $3A    ; scratch / last written reg3 (skip $4003 write if unchanged)
Temp3                  = $3B
PcmDelay               = $3F    ; PCM sample delay (rate): parameter of the PCM_* commands
PcmRequest             = $40    ; bit 7 = PCM sound pending, bits 0-6 = generator id 1-5
PcmIndex               = $41    ; offset into the generator table
PcmFlipRate            = $42    ; tone: added to PcmFlipAcc per segment; carry bumps PcmMask
PcmMask                = $43    ; tone: XOR mask on output; wave: length mask $1F/$0F
PcmFlipAcc             = $44    ; tone: accumulator; wave: direction ($00/$FF)
PcmOutVec              = $45    ; jmp vector into PcmOut_Vol0-3 (2 bytes)
PcmOutVecHi            = $46
PcmTmp                 = $47
PcmCount               = $48    ; samples left in the current segment
PcmAccelLo             = $49    ; tone: 16-bit acceleration / noise: decay
PcmAccelHi             = $4A    ; tone: acceleration high / wave: noise mask
PcmVelLo               = $4B    ; tone: 16-bit velocity / noise: 8.8 amplitude
PcmVel                 = $4C    ; tone: velocity high / noise: amplitude / wave: slope
PcmLevelLo             = $4D
PcmLevel               = $4E    ; tone/wave: current output level
PcmSegLimit            = $4F    ; max number of segments to play (+1)
PcmSegCount            = $50
ChActive               = $0301    ; per channel, stride 4 (x = 0 Sq1, 4 Sq2, 8 Tri, 12 Noise); 0 = off
ChDurCnt               = $0302    ; ticks until next event
ChPtrLo                = $0303    ; track pointer
ChPtrHi                = $0304
SfxId                  = $0311    ; SFX playing on this channel (even id; bit 0 = flag cleared by $02)
SfxTimer               = $0312    ; high nibble = frames left, low nibble = reload
SfxPtrLo               = $0313
SfxPtrHi               = $0314
ChReg0                 = $0321    ; duty / flags (bits 5-7 used)
ChReg1                 = $0322    ; sweep
ChPerLo                = $0323    ; period low
ChPerHi                = $0324    ; period high + length counter
SfxReg0                = $0331
SfxReg1                = $0332    ; $55 = SFX requested, not initialised yet
SfxReg2                = $0333
SfxReg3                = $0334
ChRepPtrLo             = $0341    ; REPEAT_CALL: pointer to the call operand
ChRepPtrHi             = $0342
ChRepCount             = $0343
ChVibDelta             = $0344    ; vibrato: current period delta
ChFixDur               = $0351    ; nonzero = all notes use this duration (no duration byte)
ChVolume               = $0352    ; current volume ($10 = constant-volume flag + 0-15)
ChEnvDelay             = $0353    ; envelope: delay before ramp / tremolo half-period
ChTranspose            = $0354    ; added to every note
ChVibWidth             = $0361    ; vibrato: steps per half cycle (0 = off)
ChVibCount             = $0362
ChVibSpeed             = $0363    ; frames per step (+1)
ChVibTimer             = $0364
ChAttack               = $0371    ; bit 7 set = restart volume envelope at each note from this volume
ChEnvTimer             = $0373
ChSlideTimer           = $0374
ChSlideCount           = $0381    ; pitch slide: steps left
ChSlideDelay           = $0382    ; pitch slide: frames before it starts
ChSlideStep            = $0383    ; pitch slide: signed period delta per step
ChSlideRev             = $0384    ; pitch slide: initial steps taken in the opposite direction
ChEnvTarget            = $0391    ; envelope: target volume (mode 1) / delta (mode 2)
ChEnvCount             = $0392
ChEnvMode              = $0393    ; 0 = off, 1 = ramp to target, 2 = tremolo
ChEnvSpeed             = $0394    ; frames per step (+1)
ChSlideSpeed           = $03A1    ; frames per slide step (+1); 0 = slide off
ChVolMode              = $03A2    ; 0 = off, $01-$7F = echo XOR, $80+ = note carries a volume byte
ChEchoVol              = $03A3    ; echo: volume of the next note
ChRetSlot              = $03A4    ; cleared per channel at song start; also CALL_A/CALL_B slots
RetA_Hi                = $03A8    ; CALL_A return address (shared by all channels!)
RetB_Lo                = $03AC    ; CALL_B return address (shared by all channels!)
RetB_Hi                = $03B0

;-----------------------------------------------------------------------------
; Hardware and code outside the disassembled range
;-----------------------------------------------------------------------------
SQ1_VOL                = $4000
SQ1_SWEEP              = $4001
SQ1_LO                 = $4002
SQ1_HI                 = $4003
DMC_RAW                = $4011
FarCall_Return         = $FFE1

; ----------------------------------------------------------------------------
; Track commands ($00-$7F)
CMD_END              = $00   ; 0 parameter byte(s)
CMD_JUMP             = $01   ; 2 parameter byte(s)
CMD_SFX_CLRFLAG      = $02   ; 0 parameter byte(s)
CMD_INSTR            = $03   ; 3 parameter byte(s)
CMD_HOLD             = $04   ; 0 parameter byte(s)
CMD_REPEAT_END       = $05   ; 0 parameter byte(s)
CMD_FIXDUR           = $06   ; 1 parameter byte(s)
CMD_FIXDUR_OFF       = $07   ; 0 parameter byte(s)
CMD_VIBRATO          = $08   ; 3 parameter byte(s)
CMD_VIBRATO_OFF      = $09   ; 0 parameter byte(s)
CMD_SLIDE_UP         = $0A   ; 5 parameter byte(s)
CMD_SLIDE_DOWN       = $0B   ; 5 parameter byte(s)
CMD_VOLUME           = $0C   ; 1 parameter byte(s)
CMD_VOL_ENV          = $0D   ; 3 parameter byte(s)
CMD_TREMOLO          = $0E   ; 3 parameter byte(s)
CMD_VOL_ENV_OFF      = $0F   ; 0 parameter byte(s)
CMD_TEMPO            = $10   ; 1 parameter byte(s)
CMD_TEMPO_ADD        = $11   ; 1 parameter byte(s)
CMD_TRANSPOSE        = $12   ; 1 parameter byte(s)
CMD_TRANSPOSE_ADD    = $13   ; 1 parameter byte(s)
CMD_TRANSPOSE_ALL    = $14   ; 1 parameter byte(s)
CMD_ATTACK_OFF       = $15   ; 0 parameter byte(s)
CMD_ATTACK_ENV       = $16   ; 3 parameter byte(s)
CMD_VIBRATO_DLY      = $17   ; 4 parameter byte(s)
CMD_PCM_TONE         = $18   ; 1 parameter byte(s)
CMD_PCM_NOISE        = $19   ; 1 parameter byte(s)
CMD_PCM_WAVE_A       = $1A   ; 1 parameter byte(s)
CMD_PCM_WAVE_B       = $1B   ; 1 parameter byte(s)
CMD_PCM_SETUP        = $1C   ; 3 parameter byte(s)
CMD_PCM_WAVE_C       = $1D   ; 1 parameter byte(s)
CMD_REPEAT_CALL      = $1E   ; 3 parameter byte(s)
CMD_ECHO             = $1F   ; 2 parameter byte(s)
CMD_ECHO_OFF         = $20   ; 0 parameter byte(s)
CMD_FIXDUR_ECHO_OFF  = $21   ; 0 parameter byte(s)
CMD_NOTEVOL_ON       = $22   ; 0 parameter byte(s)
CMD_CALL_A           = $23   ; 2 parameter byte(s)
CMD_CALL_B           = $24   ; 2 parameter byte(s)
CMD_RET_A            = $25   ; 0 parameter byte(s)
CMD_RET_B            = $26   ; 0 parameter byte(s)

RetA_Lo              = ChRetSlot   ; CALL_A return address low byte (= $03A4)

; Note bytes ($80-$FF). Pulse/triangle: $81 = C2. Noise: NZ+n = period index n.
REST = $80
N_C2   = $81
N_CS2  = $82
N_D2   = $83
N_DS2  = $84
N_E2   = $85
N_F2   = $86
N_FS2  = $87
N_G2   = $88
N_GS2  = $89
N_A2   = $8A
N_AS2  = $8B
N_B2   = $8C
N_C3   = $8D
N_CS3  = $8E
N_D3   = $8F
N_DS3  = $90
N_E3   = $91
N_F3   = $92
N_FS3  = $93
N_G3   = $94
N_GS3  = $95
N_A3   = $96
N_AS3  = $97
N_B3   = $98
N_C4   = $99
N_CS4  = $9A
N_D4   = $9B
N_DS4  = $9C
N_E4   = $9D
N_F4   = $9E
N_FS4  = $9F
N_G4   = $A0
N_GS4  = $A1
N_A4   = $A2
N_AS4  = $A3
N_B4   = $A4
N_C5   = $A5
N_CS5  = $A6
N_D5   = $A7
N_DS5  = $A8
N_E5   = $A9
N_F5   = $AA
N_FS5  = $AB
N_G5   = $AC
N_GS5  = $AD
N_A5   = $AE
N_AS5  = $AF
N_B5   = $B0
N_C6   = $B1
N_CS6  = $B2
N_D6   = $B3
N_DS6  = $B4
N_E6   = $B5
N_F6   = $B6
N_FS6  = $B7
N_G6   = $B8
N_GS6  = $B9
N_A6   = $BA
N_AS6  = $BB
N_B6   = $BC
NZ     = $C1

;=============================================================================
.segment "SOUND"    ; $851F-$CCCF (bank 3)
;=============================================================================


; ----------------------------------------------------------------------------
; PCM ("digital") sound player.
; Entered through the bank-3 jump table: X=$09 -> Pcm_PlayFullVol (game sound
; effects), X=$18/$1B -> Pcm_Play (music drums, volume set by PCM_SETUP).
; Nothing is read from ROM sample data: each sound is synthesised on the fly by
; one of three generators and written to $4011 (DMC direct load) in a busy
; loop. The generators leave through Pcm_Exit, which unwinds the far call.
;   id 1 = PcmGen_Tone  (pitch-swept sine-like tone after a noise click: kick/tom)
;   id 2 = PcmGen_Noise (decaying random noise: snare/crash)
;   id 3-5 = PcmGen_Wave (ramp segments plus masked noise)
; ----------------------------------------------------------------------------
Pcm_PlayFullVol:
        lda #$03                    ; $851F
        jsr Pcm_SetVolume           ; $8521
        lda PcmRequest              ; $8524
        and #$7F                    ; $8526
        jmp Pcm_Dispatch            ; $8528

Pcm_Play:
        lda PcmRequest              ; $852B
        and #$7F                    ; $852D
        sta PcmRequest              ; $852F

Pcm_Dispatch:
        tay                         ; $8531
        lda PcmSegLimit             ; $8532
        sta PcmSegCount             ; $8534
        lda PcmStartIdx,y           ; $8536
        sta PcmIndex                ; $8539
        dey                         ; $853B
        beq PcmDisp_Tone            ; $853C
        dey                         ; $853E
        beq PcmDisp_Noise           ; $853F

PcmDisp_Wave:
        jmp PcmGen_Wave             ; $8541

PcmDisp_Noise:
        jmp PcmGen_Noise            ; $8544

PcmDisp_Tone:
        jmp PcmGen_Tone             ; $8547
        .byte $00, $00, $00, $44                 ; ids 1-4 (id 0 = jmp operand above, id 5 = the CLC below = $18)

; A = 0-3: output volume (number of LSRs skipped). Sets PcmOutVec.
Pcm_SetVolume:
        clc                         ; $854E
        adc #<PcmOut_Vol0           ; $854F
        sta PcmOutVec               ; $8551
        lda #>PcmOut_Vol0           ; $8553
        adc #$00                    ; $8555
        sta PcmOutVecHi             ; $8557
        rts                         ; $8559

; Output one sample (A) through the selected volume entry point.
Pcm_Output:
        jmp (PcmOutVec)             ; $855A

; Sample output: 3/2/1/0 right shifts, write $4011, then delay PcmDelay*5
; cycles. Rng3 is bumped so the random generator keeps changing.
PcmOut_Vol0:
        lsr a                       ; $855D

PcmOut_Vol1:
        lsr a                       ; $855E

PcmOut_Vol2:
        lsr a                       ; $855F

PcmOut_Vol3:
        sta DMC_RAW                 ; $8560
        ldx PcmDelay                ; $8563  delay: 5 cycles per count

PcmOut_Delay:
        dex                         ; $8565
        bne PcmOut_Delay            ; $8566
        inc Rng3                    ; $8568  keep the random generator moving
        rts                         ; $856A

; PCM "wave" generator data (ids 3, 4, 5). Each byte is one ramp segment:
;   len = byte AND mask (mask $1F for id 3, $0F otherwise), slope = byte >> 5 (id 3)
;   or byte >> 4; successive segments alternate direction (up, down, up, ...).
;   $00,m  sets the noise mask (random AND m is XORed into every sample);
;   $00,$00 ends the sound.
; PCM_WAVE_A (id 3) starts here; 5-bit length, 3-bit slope
PcmWaveTbl:
        .byte $00, $0F                           ; noise mask $0F
        .byte $8F, $98
        .byte $00, $10                           ; noise mask $10
        .byte $D3, $7D, $22, $03, $D4
        .byte $00, $0F                           ; noise mask $0F
        .byte $02, $22, $98, $8F, $01, $74, $98, $9A
        .byte $75, $7B, $79

; PCM_WAVE_C (id 5) starts here; 4-bit length, 4-bit slope
        .byte $9D, $7D, $9A, $5F
        .byte $00, $07                           ; noise mask $07
        .byte $7C, $53, $4C, $0F, $52, $34, $3C, $0F
        .byte $30, $12, $12, $01, $38, $1F
        .byte $00, $03                           ; noise mask $03
        .byte $50, $18, $2C, $0E, $30, $18, $6C, $67
        .byte $35, $18, $3F, $34, $57, $34, $2C, $08
        .byte $4E, $4E, $8C, $4F
        .byte $00, $00                           ; end of sound

; PCM_WAVE_B (id 4) starts here; 4-bit length, 4-bit slope
        .byte $00, $0F                           ; noise mask $0F
        .byte $38, $68, $8B, $A7, $73, $68, $E8, $8A
        .byte $85, $53, $43, $D3, $B6, $82, $5C, $E7
        .byte $44, $C1, $78, $22, $6B, $7E, $24, $22
        .byte $AB, $4B, $44, $F4, $F2, $73, $7E, $6E
        .byte $4C, $08, $76, $5F, $6F, $4D, $68, $58
        .byte $34, $13, $F3, $4E, $A1
        .byte $00, $07                           ; noise mask $07
        .byte $32, $88, $B5
        .byte $00, $03                           ; noise mask $03
        .byte $4F, $56, $52, $74
        .byte $00, $01                           ; noise mask $01
        .byte $69, $68, $4D, $3D, $6A, $82, $63, $67
        .byte $48, $56, $4D, $48, $25, $A2, $79, $39
        .byte $F1, $24, $35, $3B, $5B, $3B, $44, $82
        .byte $38, $34, $4C, $3F, $59, $2A, $3A, $3C
        .byte $4E, $48, $2C, $1C, $39, $2A, $2C, $19
        .byte $2E, $2C, $2E, $0F, $18, $18, $2C, $0F
        .byte $11, $0C, $2C, $0E, $1C, $0F, $18, $0C
        .byte $2A, $0F
        .byte $00, $00                           ; end of sound

; PCM "noise" generator data (id 2): amplitude, decay/sample (subtracted from a
; 16-bit amplitude accumulator, 8.8), length in samples (0 = 256). $00 = end.
PcmNoiseTbl:
        .byte $6F, $FF, $04                      ; amp $6F, decay $FF, 4 samples
        .byte $40, $FF, $1C                      ; amp $40, decay $FF, 28 samples
        .byte $13, $48, $40                      ; amp $13, decay $48, 64 samples
        .byte $4F, $FF, $20                      ; amp $4F, decay $FF, 32 samples
        .byte $18, $38, $60                      ; amp $18, decay $38, 96 samples
        .byte $4F, $FF, $20                      ; amp $4F, decay $FF, 32 samples
        .byte $20, $50, $48                      ; amp $20, decay $50, 72 samples
        .byte $30, $00, $18                      ; amp $30, decay $00, 24 samples
        .byte $50, $00, $40                      ; amp $50, decay $00, 64 samples
        .byte $40, $30, $FF                      ; amp $40, decay $30, 255 samples
        .byte $11, $0C, $FF                      ; amp $11, decay $0C, 255 samples
        .byte $00                                ; end

; PCM "tone" generator data (id 1), one entry per parabolic segment.
; byte 0: bit 7 = acceleration bit 0, bits 0-6 = samples the acceleration lasts;
; byte 1: acceleration bits 1-7, sign-magnitude ($80+n = negative). The value
; added to the 16-bit velocity is (+/-)((b1 & $7F) * 2 + b0.7) * 4.
; A new entry is read every time the level crosses a multiple of 64.
PcmToneTbl:
        .byte $10, $7F                           ; len  16, accel +1016
        .byte $07, $F0                           ; len   7, accel -896
        .byte $20, $1E                           ; len  32, accel +240
        .byte $17, $94                           ; len  23, accel -160
        .byte $20, $10                           ; len  32, accel +128
        .byte $17, $8E                           ; len  23, accel -112
        .byte $16, $0C                           ; len  22, accel +96
        .byte $1C, $8A                           ; len  28, accel -80
        .byte $1E, $09                           ; len  30, accel +72
        .byte $28, $87                           ; len  40, accel -56
        .byte $28, $08                           ; len  40, accel +64
        .byte $28, $86                           ; len  40, accel -48
        .byte $28, $07                           ; len  40, accel +56
        .byte $30, $85                           ; len  48, accel -40
        .byte $30, $06                           ; len  48, accel +48
        .byte $38, $85                           ; len  56, accel -40
        .byte $26, $06                           ; len  38, accel +48
        .byte $38, $84                           ; len  56, accel -32
        .byte $27, $05                           ; len  39, accel +40
        .byte $D0, $83                           ; len  80, accel -28
        .byte $40, $03                           ; len  64, accel +24
        .byte $E0, $83                           ; len  96, accel -28
        .byte $60, $03                           ; len  96, accel +24
        .byte $70, $82                           ; len 112, accel -16
        .byte $E0, $02                           ; len  96, accel +20
        .byte $60, $82                           ; len  96, accel -16
        .byte $C0, $02                           ; len  64, accel +20
        .byte $F0, $82                           ; len 112, accel -20
        .byte $F0, $01                           ; len 112, accel +12
        .byte $F0, $82                           ; len 112, accel -20
        .byte $F0, $01                           ; len 112, accel +12
        .byte $D4, $82                           ; len  84, accel -20
        .byte $7F, $01                           ; len 127, accel +8
        .byte $70, $81                           ; len 112, accel -8
        .byte $00                                ; end

; Unreferenced: second terminator byte after PcmToneTbl
Unref_868E:
        .byte $00

; Common exit: drop the return into the far-call stub and return to bank 0.
Pcm_Exit:
        pla                         ; $868F  discard the return into the far-call stub
        pla                         ; $8690
        ldy #$00                    ; $8691
        jmp FarCall_Return          ; $8693

; ----------------------------------------------------------------------------
; Generator 1: tone (kick/tom).
; 84 samples of random noise ($3C-$4B) as an attack click, then a second-order
; oscillator: PcmLevel += PcmVel every sample, and PcmVel += PcmAccel for the
; first PcmCount samples of each segment. A new segment (with an acceleration
; of the opposite sign) starts each time the level crosses a multiple of 64, so
; the output is built from parabolic arcs - a sine-like wave whose period and
; amplitude follow the table (falling pitch). PcmFlipRate is added to
; PcmFlipAcc per segment; each carry increments PcmMask, which is XORed into
; the output (a slightly dirtier tone).
; ----------------------------------------------------------------------------
PcmGen_Tone:
        ldy #$54                    ; $8696

PcmTone_Click:
        jsr Random                  ; $8698
        and #$0F                    ; $869B
        adc #$3C                    ; $869D
        jsr Pcm_Output              ; $869F
        dey                         ; $86A2
        bne PcmTone_Click           ; $86A3
        sty PcmMask                 ; $86A5  Y = 0: clear the oscillator state
        sty PcmFlipAcc              ; $86A7
        sty PcmAccelLo              ; $86A9
        sty PcmAccelHi              ; $86AB
        sty PcmVelLo                ; $86AD
        sty PcmLevelLo              ; $86AF
        lda #$F0                    ; $86B1
        sta PcmVel                  ; $86B3
        lda #$3F                    ; $86B5
        sta PcmLevel                ; $86B7
        bne PcmTone_NextSeg         ; $86B9

PcmTone_Sample:
        dec PcmCount                ; $86BB
        bmi PcmTone_Coast           ; $86BD  acceleration only for the first PcmCount samples
        lda PcmVelLo                ; $86BF
        clc                         ; $86C1
        adc PcmAccelLo              ; $86C2
        sta PcmVelLo                ; $86C4
        lda PcmVel                  ; $86C6
        adc PcmAccelHi              ; $86C8
        sta PcmVel                  ; $86CA

PcmTone_Coast:
        lda PcmVelLo                ; $86CC
        clc                         ; $86CE
        adc PcmLevelLo              ; $86CF
        sta PcmLevelLo              ; $86D1
        lda PcmLevel                ; $86D3
        sta PcmTmp                  ; $86D5
        adc PcmVel                  ; $86D7
        sta PcmLevel                ; $86D9
        eor PcmMask                 ; $86DB
        jsr Pcm_Output              ; $86DD
        lda PcmLevel                ; $86E0
        eor PcmTmp                  ; $86E2
        and #$40                    ; $86E4  next segment when the level crosses a multiple of 64
        beq PcmTone_Sample          ; $86E6

PcmTone_NextSeg:
        dec PcmSegCount             ; $86E8
        beq PcmTone_Done            ; $86EA
        ldx PcmIndex                ; $86EC
        lda PcmToneTbl,x            ; $86EE
        sta PcmTmp                  ; $86F1
        and #$7F                    ; $86F3
        beq PcmTone_Done            ; $86F5
        sta PcmCount                ; $86F7
        inx                         ; $86F9
        lda #$00                    ; $86FA
        sta PcmAccelHi              ; $86FC
        lda PcmToneTbl,x            ; $86FE
        bpl L_870B                  ; $8701
        dec PcmAccelHi              ; $8703
        lda #$80                    ; $8705
        sec                         ; $8707
        sbc PcmToneTbl,x            ; $8708
L_870B:
        inx                         ; $870B
        stx PcmIndex                ; $870C
        asl PcmTmp                  ; $870E
        rol a                       ; $8710
        rol PcmAccelHi              ; $8711
        asl a                       ; $8713
        rol PcmAccelHi              ; $8714
        asl a                       ; $8716
        rol PcmAccelHi              ; $8717
        sta PcmAccelLo              ; $8719
        lda PcmFlipAcc              ; $871B
        adc PcmFlipRate             ; $871D
        sta PcmFlipAcc              ; $871F
        bcc PcmTone_Sample          ; $8721
        inc PcmMask                 ; $8723
        bne PcmTone_Sample          ; $8725

PcmTone_Done:
        jmp Pcm_Exit                ; $8727

; ----------------------------------------------------------------------------
; Generator 3/4/5: ramp segments. The level moves up and down in straight
; lines (slope from the table, direction alternating) with random bits
; (Random AND noise mask) XORed in.
; ----------------------------------------------------------------------------
PcmGen_Wave:
        ldx #$00                    ; $872A
        stx PcmFlipAcc              ; $872C
        ldx #$1F                    ; $872E
        cmp #$00                    ; $8730  id 3 (start index 0) uses 5-bit lengths
        beq PcmWave_SetMask         ; $8732
        ldx #$0F                    ; $8734

PcmWave_SetMask:
        stx PcmMask                 ; $8736
        lda #$3F                    ; $8738
        sta PcmLevel                ; $873A
        bne PcmWave_NextSeg         ; $873C

PcmWave_Sample:
        lda PcmVel                  ; $873E
        clc                         ; $8740
        adc PcmLevel                ; $8741
        sta PcmLevel                ; $8743
        jsr Random                  ; $8745
        and PcmAccelHi              ; $8748
        eor PcmLevel                ; $874A
        inx                         ; $874C  leftover: X is not used here
        jsr Pcm_Output              ; $874D
        dec PcmCount                ; $8750
        bpl PcmWave_Sample          ; $8752

PcmWave_NextSeg:
        dec PcmSegCount             ; $8754
        beq PcmTone_Done            ; $8756
        ldx PcmIndex                ; $8758
        lda PcmWaveTbl,x            ; $875A
        bne PcmWave_Segment         ; $875D
        lda PcmWaveTbl_1,x          ; $875F
        beq PcmTone_Done            ; $8762
        sta PcmAccelHi              ; $8764
        inx                         ; $8766
        inx                         ; $8767
        lda PcmWaveTbl,x            ; $8768

PcmWave_Segment:
        and PcmMask                 ; $876B
        sta PcmCount                ; $876D
        lda PcmWaveTbl,x            ; $876F
        inx                         ; $8772
        stx PcmIndex                ; $8773
        lsr a                       ; $8775
        lsr a                       ; $8776
        lsr a                       ; $8777
        lsr a                       ; $8778
        ldx PcmMask                 ; $8779
        cpx #$0F                    ; $877B
        beq PcmWave_SetSlope        ; $877D
        lsr a                       ; $877F

PcmWave_SetSlope:
        eor PcmFlipAcc              ; $8780  alternate the direction of each segment
        sta PcmVel                  ; $8782
        lda PcmFlipAcc              ; $8784
        eor #$FF                    ; $8786
        sta PcmFlipAcc              ; $8788
        jmp PcmWave_Sample          ; $878A

; ----------------------------------------------------------------------------
; Generator 2: decaying noise. Each sample is a random value in
; [0, amplitude) centred around $40; the amplitude falls by the decay rate.
; ----------------------------------------------------------------------------
PcmGen_Noise:
        ldy #$00                    ; $878D
        beq PcmNoise_NextSeg        ; $878F

PcmNoise_Sample:
        lda #$7F                    ; $8791
        sta PcmTmp                  ; $8793
        lda PcmVel                  ; $8795

PcmNoise_MaskLoop:
        asl a                       ; $8797
        bmi PcmNoise_Rand           ; $8798
        lsr PcmTmp                  ; $879A
        bcc PcmNoise_MaskLoop       ; $879C

PcmNoise_Rand:
        jsr Random                  ; $879E
        and PcmTmp                  ; $87A1

PcmNoise_Mod:
        sbc PcmVel                  ; $87A3  A = random mod amplitude
        bcs PcmNoise_Mod            ; $87A5
        adc PcmVel                  ; $87A7
        sta PcmTmp                  ; $87A9
        lda PcmVel                  ; $87AB
        eor #$7F                    ; $87AD  centre it: + (127 - amplitude) / 2
        lsr a                       ; $87AF
        adc PcmTmp                  ; $87B0
        jsr Pcm_Output              ; $87B2
        lda PcmVelLo                ; $87B5
        sbc PcmAccelLo              ; $87B7
        sta PcmVelLo                ; $87B9
        bcs L_87BF                  ; $87BB
        dec PcmVel                  ; $87BD
L_87BF:
        dec PcmCount                ; $87BF
        bne PcmNoise_Sample         ; $87C1

PcmNoise_NextSeg:
        dec PcmSegCount             ; $87C3
        beq PcmNoise_Done           ; $87C5
        ldx PcmIndex                ; $87C7
        lda PcmNoiseTbl,x           ; $87C9
        beq PcmNoise_Done           ; $87CC
        sta PcmVel                  ; $87CE
        lda PcmNoiseTbl_1,x         ; $87D0
        sta PcmAccelLo              ; $87D3
        lda PcmNoiseTbl_2,x         ; $87D5
        sta PcmCount                ; $87D8
        inx                         ; $87DA
        inx                         ; $87DB
        inx                         ; $87DC
        stx PcmIndex                ; $87DD
        bne PcmNoise_Sample         ; $87DF

PcmNoise_Done:
        jmp Pcm_Exit                ; $87E1

; Pseudo-random number generator (Rng0-3). Returns A = Rng0.
Random:
        lda Rng0                    ; $87E4
        eor Rng3                    ; $87E6
        adc Rng2                    ; $87E8
        sta Rng1                    ; $87EA
        lda Rng2                    ; $87EC
        rol a                       ; $87EE
        sbc Rng3                    ; $87EF
        sta Rng2                    ; $87F1
        eor Rng1                    ; $87F3
        sta Rng0                    ; $87F5
        rts                         ; $87F7

; ============================================================================
; Music_Init: start song number TempoAcc ($32). Far-call X=$03.
; ============================================================================
Music_Init:
        lda TempoAcc                ; $87F8
        tay                         ; $87FA
        asl a                       ; $87FB
        asl a                       ; $87FC
        asl a                       ; $87FD
        sta Temp                    ; $87FE
        ldx #$00                    ; $8800
        stx TempoAcc                ; $8802
        stx PcmSegLimit             ; $8804
        stx PcmFlipRate             ; $8806
        lda SongTempoTbl,y          ; $8808
        sta Tempo                   ; $880B
        lda #$03                    ; $880D
        jsr Pcm_SetVolume           ; $880F

MusicInit_ChLoop:
        tya                         ; $8812
        sta ChActive,x              ; $8813
        ldy Temp                    ; $8816
        lda SongTrackTbl,y          ; $8818
        sta ChPtrLo,x               ; $881B
        lda SongTrackTbl_Hi,y       ; $881E
        sta ChPtrHi,x               ; $8821
        lda #$01                    ; $8824
        sta ChDurCnt,x              ; $8826
        lda #$00                    ; $8829
        sta ChFixDur,x              ; $882B
        sta ChVibWidth,x            ; $882E
        sta ChSlideSpeed,x          ; $8831
        sta ChTranspose,x           ; $8834
        sta ChVolMode,x             ; $8837
        sta ChEchoVol,x             ; $883A
        sta ChRetSlot,x             ; $883D
        ldy Temp                    ; $8840
        iny                         ; $8842
        iny                         ; $8843
        sty Temp                    ; $8844
        inx                         ; $8846
        inx                         ; $8847
        inx                         ; $8848
        inx                         ; $8849
        cpx #$10                    ; $884A
        bcc MusicInit_ChLoop        ; $884C
        rts                         ; $884E

; ============================================================================
; Music_Update: called once per frame (far-call X=$06, or bank-0 $FF84).
; Tempo is a fractional accumulator: a tick happens when TempoAcc+Tempo
; carries. On tick frames tracks advance; on other frames effects run.
; ============================================================================
Music_Update:
        lda TempoAcc                ; $884F
        clc                         ; $8851
        adc Tempo                   ; $8852
        sta TempoAcc                ; $8854
        ror a                       ; $8856  carry (TempoAcc wrapped) -> bit 7 = tick
        sta TickFlag                ; $8857
        ldx #$00                    ; $8859

MusicUpd_ChLoop:
        lda ChActive,x              ; $885B
        beq MusicUpd_Sfx            ; $885E
        jsr Music_Channel           ; $8860

MusicUpd_Sfx:
        lda SfxId,x                 ; $8863
        beq MusicUpd_Next           ; $8866
        jsr Sfx_Update              ; $8868

MusicUpd_Next:
        inx                         ; $886B
        inx                         ; $886C
        inx                         ; $886D
        inx                         ; $886E
        cpx #$10                    ; $886F
        bcc MusicUpd_ChLoop         ; $8871

MusicUpd_Rts:
        rts                         ; $8873

; Process one music channel (X = 0/4/8/12).
Music_Channel:
        lda TickFlag                ; $8874
        bmi MusCh_Tick              ; $8876
        jmp Music_Effects           ; $8878

MusCh_Tick:
        dec ChDurCnt,x              ; $887B
        bne MusicUpd_Rts            ; $887E  note still sounding (no effects on tick frames)
        lda #$00                    ; $8880  a new event cancels any pitch slide
        sta ChSlideSpeed,x          ; $8882
        lda ChVolMode,x             ; $8885
        beq MusCh_Attack            ; $8888
        bmi MusCh_Attack            ; $888A
        eor ChEchoVol,x             ; $888C  echo: alternate the volume on every note
        sta ChEchoVol,x             ; $888F
        jsr SetVolume               ; $8892
        lda #$00                    ; $8895
        sta ChEnvMode,x             ; $8897

MusCh_Attack:
        lda ChAttack,x              ; $889A
        beq MusCh_Read              ; $889D
        and #$7F                    ; $889F  attack: restart the envelope from the attack volume
        sta ChVolume,x              ; $88A1
        lda #$01                    ; $88A4
        sta ChEnvMode,x             ; $88A6
        lda ChEnvCount,x            ; $88A9
        sta ChEnvDelay,x            ; $88AC

MusCh_Read:
        lda ChPtrLo,x               ; $88AF
        sta DataPtr                 ; $88B2
        lda ChPtrHi,x               ; $88B4
        sta DataPtrHi               ; $88B7

; Read events until a note is found. Commands jump back here.
ReadEvent_Y0:
        ldy #$FF                    ; $88B9

ReadEvent_Next:
        iny                         ; $88BB

ReadEvent:
        lda (DataPtr),y             ; $88BC
        bmi Ev_Note                 ; $88BE
        jmp ExecCommand             ; $88C0

; Note: $80 = rest (period 0), otherwise note + transpose indexes PeriodTbl.
; The noise channel uses (index - $82)/2 as its period instead.
Ev_Note:
        cmp #$80                    ; $88C3
        beq Ev_NoteIdx              ; $88C5
        clc                         ; $88C7
        adc ChTranspose,x           ; $88C8

Ev_NoteIdx:
        asl a                       ; $88CB
        sty Temp                    ; $88CC
        tay                         ; $88CE
        lda ChVibWidth,x            ; $88CF
        lsr a                       ; $88D2
        adc #$00                    ; $88D3
        sta ChVibCount,x            ; $88D5
        lda PeriodTbl,y             ; $88D8
        cpx #$0C                    ; $88DB  noise channel: period = (note*2 - $82) / 2
        bne Ev_SetPerLo             ; $88DD
        tya                         ; $88DF
        beq Ev_SetPerLo             ; $88E0
        sbc #$82                    ; $88E2
        lsr a                       ; $88E4

Ev_SetPerLo:
        sta ChPerLo,x               ; $88E5
        lda ChPerHi,x               ; $88E8
        and #$F8                    ; $88EB  keep the length-counter bits
        cpx #$0C                    ; $88ED
        beq Ev_SetPerHi             ; $88EF
        ora PeriodTbl_Hi,y          ; $88F1

Ev_SetPerHi:
        sta ChPerHi,x               ; $88F4
        lda ChVolMode,x             ; $88F7  note-volume mode: a volume byte follows the note
        bpl Ev_NoteVolDone          ; $88FA
        ldy Temp                    ; $88FC
        iny                         ; $88FE
        sty Temp                    ; $88FF
        lda (DataPtr),y             ; $8901
        ora #$10                    ; $8903
        jsr SetVolume               ; $8905
        lda #$00                    ; $8908
        sta ChEnvMode,x             ; $890A

Ev_NoteVolDone:
        lda SfxId,x                 ; $890D
        bne Ev_Duration             ; $8910
        jsr WriteRegsForce          ; $8912  note-on: write all registers ($4003 always)

Ev_Duration:
        ldy Temp                    ; $8915
        lda ChFixDur,x              ; $8917  fixed duration, or read a duration byte
        bne Ev_SetDuration          ; $891A
        iny                         ; $891C
        lda (DataPtr),y             ; $891D

Ev_SetDuration:
        sta ChDurCnt,x              ; $891F
        iny                         ; $8922
        tya                         ; $8923
        clc                         ; $8924
        adc DataPtr                 ; $8925
        sta ChPtrLo,x               ; $8927
        lda DataPtrHi               ; $892A
        adc #$00                    ; $892C
        sta ChPtrHi,x               ; $892E
        rts                         ; $8931

; Non-tick frame: pitch slide, vibrato and volume envelope, then write the APU.
Music_Effects:
        lda ChPerHi,x               ; $8932
        sta Temp2                   ; $8935
        lda ChSlideSpeed,x          ; $8937
        beq Fx_Vibrato              ; $893A
        lda ChSlideDelay,x          ; $893C
        beq Fx_SlideStep            ; $893F
        dec ChSlideDelay,x          ; $8941
        bne Fx_Vibrato              ; $8944

Fx_SlideStep:
        dec ChSlideTimer,x          ; $8946
        bne Fx_Vibrato              ; $8949
        lda ChSlideSpeed,x          ; $894B
        sta ChSlideTimer,x          ; $894E
        dec ChSlideCount,x          ; $8951
        bne Fx_SlideApply           ; $8954
        lda #$00                    ; $8956
        sta ChSlideSpeed,x          ; $8958

Fx_SlideApply:
        ldy #$FF                    ; $895B
        lda ChSlideRev,x            ; $895D
        beq Fx_SlideFwd             ; $8960
        dec ChSlideRev,x            ; $8962
        lda ChSlideStep,x           ; $8965
        sec                         ; $8968
        sbc #$01                    ; $8969
        eor #$FF                    ; $896B
        jmp Fx_SlideSign            ; $896D

Fx_SlideFwd:
        lda ChSlideStep,x           ; $8970

Fx_SlideSign:
        bmi Fx_SlideAdd             ; $8973
        iny                         ; $8975

Fx_SlideAdd:
        clc                         ; $8976
        adc ChPerLo,x               ; $8977
        sta ChPerLo,x               ; $897A
        tya                         ; $897D
        adc ChPerHi,x               ; $897E
        sta ChPerHi,x               ; $8981

Fx_Vibrato:
        lda ChVibWidth,x            ; $8984
        beq Fx_Envelope             ; $8987
        dec ChVibTimer,x            ; $8989
        bne Fx_Envelope             ; $898C
        lda ChVibSpeed,x            ; $898E
        sta ChVibTimer,x            ; $8991
        lda ChPerHi,x               ; $8994
        and #$07                    ; $8997
        ora ChPerLo,x               ; $8999
        beq Fx_Envelope             ; $899C
        ldy #$00                    ; $899E
        lda ChVibDelta,x            ; $89A0
        bpl Fx_VibAdd               ; $89A3
        dey                         ; $89A5

Fx_VibAdd:
        clc                         ; $89A6
        adc ChPerLo,x               ; $89A7
        sta ChPerLo,x               ; $89AA
        tya                         ; $89AD
        adc ChPerHi,x               ; $89AE
        sta ChPerHi,x               ; $89B1
        dec ChVibCount,x            ; $89B4
        bne Fx_Envelope             ; $89B7
        lda ChVibWidth,x            ; $89B9
        sta ChVibCount,x            ; $89BC
        dec ChVibDelta,x            ; $89BF
        lda ChVibDelta,x            ; $89C2
        eor #$FF                    ; $89C5
        sta ChVibDelta,x            ; $89C7

Fx_Envelope:
        lda ChEnvMode,x             ; $89CA
        beq Fx_Done                 ; $89CD
        cmp #$02                    ; $89CF
        beq Fx_EnvStep              ; $89D1
        lda ChEnvDelay,x            ; $89D3
        cmp #$01                    ; $89D6
        beq Fx_EnvStep              ; $89D8
        dec ChEnvDelay,x            ; $89DA
        bne Fx_Done                 ; $89DD

Fx_EnvStep:
        dec ChEnvTimer,x            ; $89DF
        bne Fx_Done                 ; $89E2
        lda ChEnvSpeed,x            ; $89E4
        sta ChEnvTimer,x            ; $89E7
        lda ChEnvMode,x             ; $89EA
        cmp #$01                    ; $89ED
        beq Fx_EnvRamp              ; $89EF
        lda ChVolume,x              ; $89F1
        clc                         ; $89F4
        adc ChEnvTarget,x           ; $89F5
        sta Temp3                   ; $89F8
        and #$10                    ; $89FA
        beq Fx_TremoloCount         ; $89FC
        lda Temp3                   ; $89FE
        sta ChVolume,x              ; $8A00

Fx_TremoloCount:
        dec ChEnvCount,x            ; $8A03
        bne Fx_Done                 ; $8A06
        lda ChEnvDelay,x            ; $8A08
        sta ChEnvCount,x            ; $8A0B
        dec ChEnvTarget,x           ; $8A0E
        lda ChEnvTarget,x           ; $8A11
        eor #$FF                    ; $8A14
        sta ChEnvTarget,x           ; $8A16
        jmp Fx_Done                 ; $8A19

Fx_EnvRamp:
        lda ChVolume,x              ; $8A1C
        cmp ChEnvTarget,x           ; $8A1F
        bcs Fx_EnvDown              ; $8A22
        inc ChVolume,x              ; $8A24
        bcc Fx_EnvCheck             ; $8A27

Fx_EnvDown:
        dec ChVolume,x              ; $8A29

Fx_EnvCheck:
        lda ChVolume,x              ; $8A2C
        eor ChEnvTarget,x           ; $8A2F
        and #$0F                    ; $8A32
        bne Fx_Done                 ; $8A34
        sta ChEnvMode,x             ; $8A36

Fx_Done:
        lda SfxId,x                 ; $8A39
        beq WriteRegs               ; $8A3C
        rts                         ; $8A3E

; Write the channel shadow registers to the APU ($4003 only when it changed).
WriteRegsForce:
        lda #$FF                    ; $8A3F
        sta Temp2                   ; $8A41
        lda ChReg1,x                ; $8A43
        sta SQ1_SWEEP,x             ; $8A46

WriteRegs:
        lda ChReg0,x                ; $8A49
        and #$E0                    ; $8A4C
        ora ChVolume,x              ; $8A4E
        sta SQ1_VOL,x               ; $8A51
        lda ChPerLo,x               ; $8A54
        sta SQ1_LO,x                ; $8A57
        lda ChPerHi,x               ; $8A5A
        cmp Temp2                   ; $8A5D  skip $4003 if unchanged (avoids a phase reset)
        beq WriteRegs_Rts           ; $8A5F
        sta SQ1_HI,x                ; $8A61

WriteRegs_Rts:
        rts                         ; $8A64

; ============================================================================
; Sfx_Play*: start sound effect Temp ($39) on one channel.
; Far-call X=$0C/$0F/$12/$15. Effects $7A/$7B cannot be interrupted.
; ============================================================================
Sfx_PlaySq1:
        ldx #$00                    ; $8A65
        beq Sfx_Play                ; $8A67

Sfx_PlaySq2:
        ldx #$04                    ; $8A69
        bne Sfx_Play                ; $8A6B

Sfx_PlayTri:
        ldx #$08                    ; $8A6D
        bne Sfx_Play                ; $8A6F

Sfx_PlayNoise:
        ldx #$0C                    ; $8A71

Sfx_Play:
        lda SfxId,x                 ; $8A73
        and #$FE                    ; $8A76
        cmp #$7A                    ; $8A78  effects $7A/$7B cannot be interrupted
        beq Sfx_Play_Rts            ; $8A7A
        lda Temp                    ; $8A7C
        cmp SfxId,x                 ; $8A7E
        beq WriteRegs_Rts           ; $8A81
        pha                         ; $8A83
        lda #$55                    ; $8A84  SfxReg1 = $55: initialise on the next update
        sta SfxReg1,x               ; $8A86
        pla                         ; $8A89
        sta SfxId,x                 ; $8A8A

Sfx_Play_Rts:
        rts                         ; $8A8D

; First frame of a sound effect: read its 3-byte header.
Sfx_Start:
        lda SfxId,x                 ; $8A8E
        and #$FE                    ; $8A91
        tay                         ; $8A93
        lda SfxTbl,y                ; $8A94
        sta DataPtr                 ; $8A97
        lda SfxTbl_Hi,y             ; $8A99
        sta DataPtrHi               ; $8A9C
        ldy #$00                    ; $8A9E
        tya                         ; $8AA0
        sta ChVibWidth,x            ; $8AA1
        lda (DataPtr),y             ; $8AA4
        and #$0F                    ; $8AA6
        sta SfxTimer,x              ; $8AA8
        lda (DataPtr),y             ; $8AAB
        and #$F0                    ; $8AAD
        sta SfxReg0,x               ; $8AAF
        iny                         ; $8AB2
        lda (DataPtr),y             ; $8AB3
        sta SfxReg1,x               ; $8AB5
        iny                         ; $8AB8
        lda (DataPtr),y             ; $8AB9
        sta SfxReg3,x               ; $8ABB
        jmp Sfx_SavePtr             ; $8ABE

; Per-frame sound effect update (overrides the music on that channel).
Sfx_Update:
        lda SfxReg1,x               ; $8AC1
        cmp #$55                    ; $8AC4
        beq Sfx_Start               ; $8AC6
        lda SfxTimer,x              ; $8AC8
        sec                         ; $8ACB
        sbc #$10                    ; $8ACC  count frames in the high nibble
        bcc Sfx_Step                ; $8ACE
        sta SfxTimer,x              ; $8AD0
        rts                         ; $8AD3

Sfx_Step:
        asl a                       ; $8AD4
        asl a                       ; $8AD5
        asl a                       ; $8AD6
        asl a                       ; $8AD7
        sta Temp                    ; $8AD8
        ora SfxTimer,x              ; $8ADA
        sta SfxTimer,x              ; $8ADD
        lda SfxPtrLo,x              ; $8AE0
        sta DataPtr                 ; $8AE3
        lda SfxPtrHi,x              ; $8AE5
        sta DataPtrHi               ; $8AE8
        ldy #$00                    ; $8AEA

Sfx_ReadStep:
        lda (DataPtr),y             ; $8AEC
        bne Sfx_Event               ; $8AEE
        sta SfxId,x                 ; $8AF0  effect over: hand the channel back to the music
        lda ChActive,x              ; $8AF3
        bne Sfx_RestoreMusic        ; $8AF6

SilenceChannel:
        lda #$10                    ; $8AF8
        sta SQ1_VOL,x               ; $8AFA
        rts                         ; $8AFD

Sfx_RestoreMusic:
        jmp WriteRegsForce          ; $8AFE

Sfx_Event:
        cmp #$10                    ; $8B01
        bcc ExecCommand             ; $8B03  $01-$0F: command (only $02 and $04 belong here)
        lsr a                       ; $8B05
        lsr a                       ; $8B06
        lsr a                       ; $8B07
        lsr a                       ; $8B08
        sta Temp                    ; $8B09
        lda SfxReg0,x               ; $8B0B
        and #$F0                    ; $8B0E
        ora Temp                    ; $8B10
        sta SfxReg0,x               ; $8B12
        sta SQ1_VOL,x               ; $8B15
        lda SfxReg1,x               ; $8B18
        sta SQ1_SWEEP,x             ; $8B1B
        lda (DataPtr),y             ; $8B1E
        and #$07                    ; $8B20
        sta Temp                    ; $8B22
        lda SfxReg3,x               ; $8B24
        and #$07                    ; $8B27
        cmp Temp                    ; $8B29  write $4003 only when the period high bits change
        beq Sfx_SetLo               ; $8B2B
        lda SfxReg3,x               ; $8B2D
        and #$F8                    ; $8B30
        ora Temp                    ; $8B32
        sta SfxReg3,x               ; $8B34
        sta SQ1_HI,x                ; $8B37

Sfx_SetLo:
        iny                         ; $8B3A
        lda (DataPtr),y             ; $8B3B
        sta SfxReg2,x               ; $8B3D
        sta SQ1_LO,x                ; $8B40

Sfx_SavePtr:
        tya                         ; $8B43
        sec                         ; $8B44
        adc DataPtr                 ; $8B45
        sta SfxPtrLo,x              ; $8B47
        lda DataPtrHi               ; $8B4A
        adc #$00                    ; $8B4C
        sta SfxPtrHi,x              ; $8B4E
        rts                         ; $8B51

; Dispatch command A (< $80) through CmdTbl. Music handlers continue at
; ReadEvent; SFX-only handlers ($02, $04) continue in the SFX reader.
ExecCommand:
        stx Temp                    ; $8B52
        asl a                       ; $8B54
        tax                         ; $8B55
        lda CmdTbl,x                ; $8B56
        sta Temp2                   ; $8B59
        lda CmdTbl_Hi,x             ; $8B5B
        sta Temp3                   ; $8B5E
        ldx Temp                    ; $8B60
        jmp (Temp2)                 ; $8B62

CmdTbl:
        .word Cmd_End                            ; $00 END
        .word Cmd_Jump                           ; $01 JUMP
