; Sound effect pointers, indexed by id/2 (ids are even; bit 0 is a flag).
; SFX format: header (reg0 high nibble | frames-per-step - 1, sweep, reg3),
; then 2-byte steps: (volume << 4 | period bits 8-10), period bits 0-7.
; $00 ends the effect; $02 clears the id flag bit; $04 holds one step.
SfxTbl:
        .word Sfx_00, Sfx_02, Sfx_04, Sfx_06     ; id $00-$06
        .word Sfx_08, Sfx_0A, Sfx_0C, Sfx_0E     ; id $08-$0E
        .word Sfx_10, Sfx_12, Sfx_14, Sfx_16     ; id $10-$16
        .word Sfx_18, Sfx_1A, Sfx_1C, Sfx_1E     ; id $18-$1E
        .word Sfx_20, Sfx_22, Sfx_24, Sfx_26     ; id $20-$26
        .word Sfx_28, Sfx_2A, Sfx_2C, Sfx_2E     ; id $28-$2E
        .word Sfx_30, Sfx_32, Sfx_34, Sfx_36     ; id $30-$36
        .word Sfx_38, Sfx_3A, Sfx_3C, Sfx_3E     ; id $38-$3E
        .word Sfx_40, Sfx_42, Sfx_44, Sfx_46     ; id $40-$46
        .word Sfx_48, Sfx_4A, Sfx_4C, Sfx_4E     ; id $48-$4E
        .word Sfx_50, Sfx_52, Sfx_54, Sfx_56     ; id $50-$56
        .word Sfx_58, Sfx_5A, Sfx_5C, Sfx_5E     ; id $58-$5E
        .word Sfx_60, Sfx_62, Sfx_64, Sfx_66     ; id $60-$66
        .word Sfx_68, Sfx_6A, Sfx_6C, Sfx_6E     ; id $68-$6E
        .word Sfx_70, Sfx_72, Sfx_74, Sfx_76     ; id $70-$76
        .word Sfx_78, Sfx_7A, Sfx_7C, Sfx_7E     ; id $78-$7E
        .word Sfx_80, Sfx_82, Sfx_84, Sfx_86     ; id $80-$86
        .word Sfx_88, Sfx_8A, Sfx_8C, Sfx_8E     ; id $88-$8E
        .word Sfx_90, Sfx_92, Sfx_94, Sfx_96     ; id $90-$96
        .word Sfx_98, Sfx_9A, Sfx_9C, Sfx_9E     ; id $98-$9E
        .word Sfx_A0, Sfx_A2, Sfx_A4, Sfx_A6     ; id $A0-$A6
        .word Sfx_A8                             ; id $A8-$A8

Sfx_00:
        .byte $F0, $08, $00                      ; reg0 $F0, 1 frame(s)/step, sweep $08, reg3 $00
        .byte CMD_END

Sfx_02:
        .byte $71, $00, $07                      ; reg0 $70, 2 frame(s)/step, sweep $00, reg3 $07
        .byte $81,$00,  $61,$00,  $41,$00,  $12,$00
        .byte CMD_END

Sfx_04:
        .byte $71, $08, $07                      ; reg0 $70, 2 frame(s)/step, sweep $08, reg3 $07
        .byte $F0,$0B,  $50,$00,  $F0,$07
        .byte CMD_END

Sfx_06:
        .byte $30, $08, $07                      ; reg0 $30, 1 frame(s)/step, sweep $08, reg3 $07
        .byte $C0,$0D
        .byte CMD_END

Sfx_08:
        .byte $30, $08, $07                      ; reg0 $30, 1 frame(s)/step, sweep $08, reg3 $07
        .byte $80,$0B
        .byte CMD_END

Sfx_0A:
        .byte $74, $08, $07                      ; reg0 $70, 5 frame(s)/step, sweep $08, reg3 $07
        .byte CMD_SFX_CLRFLAG
        .byte $F0,$0C,  $E0,$0D,  $D0,$0E,  $C0,$0E,  $B0,$0E,  $A0,$0F
        .byte $90,$0F,  $80,$0E,  $70,$0F,  $60,$0F,  $50,$0F,  $40,$0E
        .byte $30,$0F,  $20,$0F,  $10,$0F
        .byte CMD_END

Sfx_0C:
        .byte $B4, $8B, $07                      ; reg0 $B0, 5 frame(s)/step, sweep $8B, reg3 $07
        .byte $81,$FF
        .byte CMD_END

Sfx_0E:
        .byte $72, $08, $07                      ; reg0 $70, 3 frame(s)/step, sweep $08, reg3 $07
        .byte $A0,$07
        .byte CMD_SFX_CLRFLAG
        .byte $F0,$0B,  $C0,$0E,  $80,$0F,  $70,$0F,  $60,$0F,  $50,$0F
        .byte $40,$0F,  $30,$0F,  $20,$0F,  $10,$0F
        .byte CMD_END

Sfx_10:
        .byte $B8, $83, $07                      ; reg0 $B0, 9 frame(s)/step, sweep $83, reg3 $07
        .byte $C0,$9F
        .byte CMD_END

Sfx_12:
        .byte $7F, $B6, $07                      ; reg0 $70, 16 frame(s)/step, sweep $B6, reg3 $07
        .byte $11,$00,  $21,$20,  $31,$40,  $41,$60,  $51,$80,  $61,$A0
        .byte $71,$C0,  $81,$E8,  $92,$28,  $A2,$58,  $B2,$80,  $C2,$B0
        .byte $D3,$00,  $E3,$30,  $F3,$60
        .byte CMD_END

Sfx_14:
        .byte $73, $01, $07                      ; reg0 $70, 4 frame(s)/step, sweep $01, reg3 $07
        .byte $12,$00,  $12,$10,  $22,$00,  $22,$10,  $32,$00,  $32,$10
